	('2025-09-25 10:49:30.181', '2025-09-25 11:13:25.345', NULL, 0, 0, '/assets/prompt-CEUUcXkn.png', 'sys_agent_mysql_generate_echarts_by_chart_type__zh-Hant', '数据库问答@根据指定的图表类型生成 ECharts 图表(zh-Hant)', 'company', '1699', '/lesson-plan', 'user', 'published', NULL, '', 'disabled');

